update public.audit_user_facing_groups as target set
  focus=content.focus,
  passed_message=content.passed_message,
  failed_message=content.failed_message,
  advisory_message=content.advisory_message,
  not_applicable_message=content.not_applicable_message,
  unable_to_test_message=content.unable_to_test_message,
  recommendation=content.recommendation,
  example_fix=content.example_fix,
  reference_label=content.reference_label,
  evidence_presentation=content.evidence_presentation,
  occurrence_presentation=content.occurrence_presentation,
  configuration_version=content.configuration_version,
  changed_at=now()
from content
where target.id=content.id;

do $$
begin
  if (select count(*) from public.audit_user_facing_groups where configuration_version = 2 and focus is not null) <> 121 then
    raise exception 'Stage 4 content must match all 121 approved user-facing groups';
  end if;
end $$;

